package com.example.techfix.ui;
public class AppointmentDisplay { private final int appointmentId; private final String date,branchName,serviceName,status; public AppointmentDisplay(int id,String date,String branch,String service,String status){this.appointmentId=id;this.date=date;this.branchName=branch;this.serviceName=service;this.status=status;} public int getAppointmentId(){return appointmentId;} public String getDate(){return date;} public String getBranchName(){return branchName;} public String getServiceName(){return serviceName;} public String getStatus(){return status;} }